fn totals_values() {
    assert_eq!(total(&[2, 3, 5]), 10);
}

#[test]
fn totals_empty_input() {
    assert_eq!(total(&[]), 0);
}

#[test]
fn totals_negative_values() {
    assert_eq!(total(&[-4, 1]), -3);
}

